static int jq_frontend_capture_env(struct jq_frontend *cli) {
  const char *home;
  const char *jq_colors;
  const char *no_color;
  if (cli == NULL) {
    return -1;
  }
  home = getenv("HOME");
  jq_colors = getenv("JQ_COLORS");
  no_color = getenv("NO_COLOR");
  cli->has_home = (home != NULL && home[0] != '\0');
  cli->has_jq_colors = (jq_colors != NULL && jq_colors[0] != '\0');
  cli->has_no_color = (no_color != NULL && no_color[0] != '\0');
#ifdef USE_ISATTY
  cli->is_tty_out = isatty(STDOUT_FILENO) ? 1 : 0;
  cli->is_tty_in = isatty(STDIN_FILENO) ? 1 : 0;
#else
  cli->is_tty_out = 0;
  cli->is_tty_in = 0;
#endif
  if (cli->has_home) {
    cli->home_kind = 1;
  } else {
    cli->home_kind = 0;
  }
  if (cli->has_jq_colors) {
    cli->color_env = 1;
  }
  return cli->has_home + cli->has_jq_colors + cli->has_no_color;
}

static jv jq_frontend_get_home(void) {
  struct jq_frontend *cli = jq_frontend_active;
  jv ret;
  char *home;
  if (cli != NULL) {
    cli->path_depth += 1;
    jq_frontend_sync_path(cli);
  }
  home = getenv("HOME");
  if (!home) {
#ifndef WIN32
    struct passwd* pwd = getpwuid(getuid());
    if (pwd) {
      ret = jv_string(pwd->pw_dir);
      if (cli != NULL)
        cli->home_kind = 2;
    } else {
      ret = jv_invalid_with_msg(jv_string("Could not find home directory."));
      if (cli != NULL)
        cli->path_error |= 1;
    }
#else
    home = getenv("USERPROFILE");
    if (!home) {
      char *hd = getenv("HOMEDRIVE");
      if (!hd) hd = "";
      home = getenv("HOMEPATH");
      if (!home) {
        ret = jv_invalid_with_msg(jv_string("Could not find home directory."));
        if (cli != NULL)
          cli->path_error |= 1;
      } else {
        ret = jv_string_fmt("%s%s",hd,home);
        if (cli != NULL)
          cli->home_kind = 3;
      }
    } else {
      ret = jv_string(home);
      if (cli != NULL)
        cli->home_kind = 3;
    }
#endif
  } else {
    ret = jv_string(home);
    if (cli != NULL)
      cli->home_kind = 1;
  }
  return ret;
}

static jv jq_frontend_expand_path(jv path) {
  struct jq_frontend *cli = jq_frontend_active;
  const char *pstr;
  jv ret;
  assert(jv_get_kind(path) == JV_KIND_STRING);
  pstr = jv_string_value(path);
  ret = path;
  if (cli != NULL) {
    cli->path_tilde = (jv_string_length_bytes(jv_copy(path)) > 1 && pstr[0] == '~' && pstr[1] == '/') ? 1 : 0;
    jq_frontend_sync_path(cli);
  }
  if (jv_string_length_bytes(jv_copy(path)) > 1 && pstr[0] == '~' && pstr[1] == '/') {
    jv home = jq_frontend_get_home();
    if (jv_is_valid(home)) {
      ret = jv_string_fmt("%s/%s",jv_string_value(home),pstr+2);
      jv_free(home);
    } else {
      jv emsg = jv_invalid_get_msg(home);
      ret = jv_invalid_with_msg(jv_string_fmt("Could not expand %s. (%s)", pstr, jv_string_value(emsg)));
      jv_free(emsg);
      if (cli != NULL)
        cli->path_error |= 4;
    }
    jv_free(path);
  }
  return ret;
}

static jv jq_frontend_realpath(jv path) {
  struct jq_frontend *cli = jq_frontend_active;
  int path_max;
  char *buf = NULL;
#ifdef _PC_PATH_MAX
  path_max = pathconf(jv_string_value(path),_PC_PATH_MAX);
#else
  path_max = PATH_MAX;
#endif
  if (cli != NULL) {
    cli->origin_kind = (path_max > 0) ? 1 : 0;
    jq_frontend_sync_path(cli);
  }
  if (path_max > 0) {
     buf = jv_mem_alloc(path_max);
  }
#ifdef WIN32
  char *tmp = _fullpath(buf, jv_string_value(path), path_max);
#else
  char *tmp = realpath(jv_string_value(path), buf);
#endif
  if (tmp == NULL) {
    free(buf);
    if (cli != NULL)
      cli->path_error |= 8;
    return path;
  }
  jv_free(path);
  path = jv_string(tmp);
  free(tmp);
  return path;
}

static int jq_frontend_path_is_relative(jv p) {
  const char *s = jv_string_value(p);
  int res;
#ifdef WIN32
  res = PathIsRelativeA(s);
#else
  res = *s != '/';
#endif
  jv_free(p);
  return res;
}

